probe.stepText:
import { writeFile } from 'node:fs/promises';
import { join } from 'node:path';

import { Given } from '@cucumber/cucumber';

Given('the cache parent is a regular file', async function () {
  const homebridge = await this.homebridge();
  const file = join(homebridge.storagePath, 'regular-file');
  await writeFile(file, 'x');
  homebridge.storagePath = file;
});

probe.runnerText:
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';

const result = spawnSync('./node_modules/.bin/cucumber-js', ['--config', '.phase8-cache-access-config.json'], {
  cwd: process.cwd(),
  encoding: 'utf8',
});
process.stdout.write(result.stdout);
process.stderr.write(result.stderr);
assert.equal(result.status, 1, 'a non-ENOENT cache access failure must fail the cache-absence Then');
assert.match(result.stdout + result.stderr, /ENOTDIR/);
